func valueInvoiceShare(p unsafe.Pointer, c int32) any {
	r := (*invoiceshare.InvoiceShare)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.InvoiceID)
	case 4:
		return string(r.SharedWithID)
	case 5:
		return string(r.SharedByID)
	case 6:
		if r.Note == "" {
			return nil
		}
		return r.Note
	case 7:
		return string(r.Tab)
	case 8:
		return int64(r.ShareCount)
	case 9:
		return r.FirstSharedAt
	case 10:
		return r.LastSharedAt
	case 11:
		return r.CreatedAt
	case 12:
		return r.UpdatedAt
	}
	return nil
}

